     });
   };

+  const handleDownloadZip = async () => {
+    if (selectedImages.length < 2) {
+      toast.error(t('zipNoImages'));
+      return;
+    }
+
+    const toastId = toast.loading(
+      t('zipImages', { count: selectedImages.length })
+    );
+
+    try {
+      const zip = new JSZip();
+
+      // Fetch all images in parallel
+      const results = await Promise.allSettled(
+        selectedImages.map(async (img, i) => {
+          const src = Array.isArray(img.src)
+            ? (img.src[img.currentIndex ?? 0] ?? img.src[0])
+            : img.src;
+
+          if (!src) throw new Error('No image source');
+
+          // Convert S3 URL if needed
+          let httpUrl = src;
+          if (src.startsWith('s3://')) {
+            const res = await fetch('/api/s3-media-url', {
+              method: 'POST',
+              headers: { 'Content-Type': 'application/json' },
+              body: JSON.stringify({ s3Url: src })
+            });
+            if (!res.ok)
+              throw new Error(`S3 URL conversion failed: ${res.status}`);
+            const data = await res.json();
+            httpUrl = data.url;
+          }
+
+          const response = await fetch(httpUrl);
+          if (!response.ok)
+            throw new Error(`Image fetch failed: ${response.status}`);
+          const blob = await response.blob();
+
+          // Determine file extension from Content-Type
+          const ext = blob.type.includes('png')
+            ? 'png'
+            : blob.type.includes('webp')
+              ? 'webp'
+              : 'jpg';
+
+          return { index: i, blob, ext };
+        })
+      );
+
+      // Add successful downloads to ZIP
+      for (const r of results) {
+        if (r.status === 'fulfilled') {
+          zip.file(
+            `image_${r.value.index + 1}.${r.value.ext}`,
+            r.value.blob
+          );
+        }
+      }
+
+      // Guard against empty ZIP
+      if (Object.keys(zip.files).length === 0) {
+        toast.error(t('zipNoImages'), { id: toastId });
+        return;
+      }
+
+      const zipBlob = await zip.generateAsync({ type: 'blob' });
+      const blobUrl = URL.createObjectURL(zipBlob);
+      triggerDownload(blobUrl, 'canvas_images.zip');
+      URL.revokeObjectURL(blobUrl);
+
+      const failedCount = results.filter(
+        (r) => r.status === 'rejected'
+      ).length;
+      toast.success(
+        failedCount > 0
+          ? `Downloaded ${results.length - failedCount}/${results.length} images`
+          : tCanvas('actionsInfo.download.imageDownloadedSuccessfully'),
+        { id: toastId }
+      );
+
+      mixpanel.track('[Canvas] ZIP Download', {
+        source: 'toolbar_dropdown',
+        imageCount: selectedImages.length
+      });
+    } catch (error) {
+      console.error('Failed to download images as ZIP:', error);
+      toast.error(tCanvas('exportFailedGeneral'), { id: toastId });
+    }
+  };
+
   return (
     <>
       <DropdownMenu>
